using System;
using System.Collections.Generic;
using System.Linq;
using AICad.Contracts;
using Autodesk.AutoCAD.ApplicationServices;
using Autodesk.AutoCAD.DatabaseServices;
using Autodesk.AutoCAD.Geometry;
using Autodesk.AutoCAD.EditorInput;
using Autodesk.AutoCAD.Runtime;
using Newtonsoft.Json.Linq;
using JsonUtil=AICad.Contracts.Json;
using AcApp=Autodesk.AutoCAD.ApplicationServices.Core.Application;
[assembly:CommandClass(typeof(AICad.Bridge.SourceTaskCommands))]
namespace AICad.Bridge;
internal static class OutputAnchors {
 internal static Dictionary<string,List<Point3d>> Scan(Database db,Transaction tx){var result=new Dictionary<string,List<Point3d>>(StringComparer.Ordinal);var bt=(BlockTable)tx.GetObject(db.BlockTableId,OpenMode.ForRead);var ms=(BlockTableRecord)tx.GetObject(bt[BlockTableRecord.ModelSpace],OpenMode.ForRead);foreach(ObjectId id in ms){if(tx.GetObject(id,OpenMode.ForRead) is not BlockReference b)continue;var def=(BlockTableRecord)tx.GetObject(b.BlockTableRecord,OpenMode.ForRead);if(def.Name!="AI_OUTPUT_POINT")continue;string key="";foreach(ObjectId aid in b.AttributeCollection){var a=(AttributeReference)tx.GetObject(aid,OpenMode.ForRead);if(a.Tag=="TASK_ID")key=a.TextString;}if(key=="")continue;if(!result.ContainsKey(key))result[key]=new();result[key].Add(b.Position);}return result;}
 internal static ObjectId Create(Database db,Transaction tx,string task,Point3d at){var bt=(BlockTable)tx.GetObject(db.BlockTableId,OpenMode.ForRead);ObjectId definition;if(bt.Has("AI_OUTPUT_POINT"))definition=bt["AI_OUTPUT_POINT"];else{bt.UpgradeOpen();var def=new BlockTableRecord{Name="AI_OUTPUT_POINT"};definition=bt.Add(def);tx.AddNewlyCreatedDBObject(def,true);foreach(Entity e in new Entity[]{new Circle(Point3d.Origin,Vector3d.ZAxis,140),new Line(new Point3d(-220,0,0),new Point3d(220,0,0)),new Line(new Point3d(0,-220,0),new Point3d(0,220,0)),new DBText{Position=new Point3d(250,80,0),Height=100,TextString="DAT KET QUA"},new AttributeDefinition{Tag="TASK_ID",Prompt="Task",Height=80,Position=new Point3d(250,-80,0),Invisible=false}}){e.ColorIndex=4;def.AppendEntity(e);tx.AddNewlyCreatedDBObject(e,true);}}
 var ms=(BlockTableRecord)tx.GetObject(bt[BlockTableRecord.ModelSpace],OpenMode.ForWrite);var block=new BlockReference(at,definition);ms.AppendEntity(block);tx.AddNewlyCreatedDBObject(block,true);var stored=(BlockTableRecord)tx.GetObject(definition,OpenMode.ForRead);foreach(ObjectId id in stored)if(tx.GetObject(id,OpenMode.ForRead) is AttributeDefinition a){var attr=new AttributeReference();attr.SetAttributeFromBlock(a,block.BlockTransform);attr.TextString=task;block.AttributeCollection.AppendAttribute(attr);tx.AddNewlyCreatedDBObject(attr,true);}return block.ObjectId;}
}
public sealed class SourceTaskCommands {
 [CommandMethod("AICADOUTPUT",CommandFlags.Modal)]public void AddOutput(){var p=Plugin.Current!;var d=AcApp.DocumentManager.MdiActiveDocument;try{var pick=d.Editor.GetEntity("\nChon block khung AI_TASK: ");if(pick.Status!=PromptStatus.OK)return;var task=Reader.Scan(d).SingleOrDefault(t=>t.Handle==pick.ObjectId.Handle.ToString())??throw new CadException("INVALID_TASK","Chon dung khung AI_TASK.");if(task.OutputPoint!=null){d.Editor.WriteMessage("\nDa co diem AI_OUTPUT_POINT. Dung MOVE de doi vi tri.");return;}using var tx=d.Database.TransactionManager.StartTransaction();OutputAnchors.Create(d.Database,tx,task.TaskId,new Point3d(task.Scope[0].X,task.Scope[0].Y,0));tx.Commit();d.Editor.WriteMessage("\nDa tao diem dat ket qua. MOVE block AI_OUTPUT_POINT tuy y truoc khi tao preview.");}catch(System.Exception e){d.Editor.WriteMessage("\nAI CAD: "+e.Message);}}
 [CommandMethod("AICADSOURCETASK",CommandFlags.Modal|CommandFlags.NoUndoMarker)]public void SourceTask(){var p=Plugin.Current!;var request=p.NextSourceTask;p.NextSourceTask=null;if(request==null)return;try{var d=p.Context.Resolve(request.Value<string>("documentId")!,request.Value<string>("revision")!);if(AcApp.DocumentManager.MdiActiveDocument!=d||!d.Database.TileMode||d.Database.Insunits!=UnitsValue.Millimeters)throw new CadException("WRONG_CONTEXT","Mo dung DWG, Model va don vi mm.");NativeWriteGuard.Check(d);string id=JsonUtil.Id(request.Value<string>("sourceId")!),taskId="IMG_"+id.Substring(0,8),skillId=JsonUtil.Name(request.Value<string>("skillId")!),templateId=JsonUtil.Name(request.Value<string>("templateId")!);var store=new ContentStore(p.Config.ContentRoot);var skill=store.Skill(skillId);if(skill.Builder!="source"||skill.TemplateId!=templateId||!store.Enabled(skillId))throw new CadException("SKILL_MISMATCH","Skill nguon khong khop thu vien.");_ = store.Template(templateId);double width=request.Value<double>("width"),height=request.Value<double>("height");if(width<1000||height<1000||width>100000||height>100000)throw new CadException("INVALID_SCOPE","Kich thuoc khung khong hop le.");var tasks=Reader.Scan(d);var existing=tasks.SingleOrDefault(t=>t.TaskId==taskId);if(existing!=null){if(existing.SkillId!=skillId||existing.TemplateId!=templateId)throw new CadException("TASK_CHANGED","Khung nguon da dung thu vien khac.");if(existing.OutputPoint==null){using var tx=d.Database.TransactionManager.StartTransaction();OutputAnchors.Create(d.Database,tx,taskId,new Point3d(existing.Scope[0].X,existing.Scope[0].Y,0));tx.Commit();}return;}
 double x=tasks.Count==0?0:tasks.SelectMany(t=>t.Scope).Max(pt=>pt.X)+2000,y=tasks.Count==0?0:tasks.SelectMany(t=>t.Scope).Min(pt=>pt.Y);Create(d,x,y,width,height,taskId,skillId,templateId,id);d.Editor.WriteMessage("\nAI CAD: Khung nguon va diem AI_OUTPUT_POINT da tao trong DWG dang ket noi. MOVE diem dat neu can, sau do tao ke hoach trong app.");
 }catch(System.Exception e){JsonUtil.Atomic(System.IO.Path.Combine(p.Config.DataRoot,"last-source-task-error.json"),new{at=DateTime.UtcNow,sourceId=request.Value<string>("sourceId"),code=e is CadException ce?ce.Code:"CAD_ERROR",message=e.Message});AcApp.DocumentManager.MdiActiveDocument?.Editor.WriteMessage("\nAI CAD: "+e.Message);}}
 internal static void Create(Document d,double x,double y,double width,double height,string task,string skill,string template,string source){d.Editor.Command("_.UNDO","_BEGIN");try{using var tx=d.Database.TransactionManager.StartTransaction();var bt=(BlockTable)tx.GetObject(d.Database.BlockTableId,OpenMode.ForWrite);var def=new BlockTableRecord{Name="AI_TASK_SOURCE_"+Guid.NewGuid().ToString("N").Substring(0,8)};var defId=bt.Add(def);tx.AddNewlyCreatedDBObject(def,true);var boundary=new Polyline(4);foreach(var pt in new[]{new Point2d(0,0),new Point2d(width,0),new Point2d(width,height),new Point2d(0,height)})boundary.AddVertexAt(boundary.NumberOfVertices,pt,0,0,0);boundary.Closed=true;boundary.ColorIndex=8;def.AppendEntity(boundary);tx.AddNewlyCreatedDBObject(boundary,true);var values=new Dictionary<string,string>{{"TASK_ID",task},{"SKILL_ID",skill},{"TEMPLATE_ID",template},{"STATUS","PENDING"},{"DEPENDS_ON",""},{"PROMPT","Nguon PDF/anh; ket qua dat tai AI_OUTPUT_POINT"},{"SOURCE_REF",source},{"OUTPUT_REQUIRED","1"}};foreach(var pair in values){var attr=new AttributeDefinition{Tag=pair.Key,Prompt=pair.Key,TextString=pair.Value,Height=100,Invisible=true};def.AppendEntity(attr);tx.AddNewlyCreatedDBObject(attr,true);}var ms=(BlockTableRecord)tx.GetObject(bt[BlockTableRecord.ModelSpace],OpenMode.ForWrite);var block=new BlockReference(new Point3d(x,y,0),defId);ms.AppendEntity(block);tx.AddNewlyCreatedDBObject(block,true);foreach(ObjectId aid in def)if(tx.GetObject(aid,OpenMode.ForRead) is AttributeDefinition a){var ar=new AttributeReference();ar.SetAttributeFromBlock(a,block.BlockTransform);ar.TextString=values[a.Tag];block.AttributeCollection.AppendAttribute(ar);tx.AddNewlyCreatedDBObject(ar,true);}OutputAnchors.Create(d.Database,tx,task,new Point3d(x,y,0));tx.Commit();}finally{d.Editor.Command("_.UNDO","_END");}}
}
